// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address actor) public {
        // admissible domain: a real external account distinct from the contract and owner
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // owner opens the contract to the public
        vm.prank(address(this));
        c.OpenToThePublic();

        // any real person can then place a wager (betLimit is 0, wagers[actor]==0)
        vm.deal(actor, 1);
        vm.prank(actor, actor); // ensure msg.sender == tx.origin (onlyRealPeople)
        bool ok;
        try c.wager{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
